  $ap2json${"slug": "anatomy-and-physiology-ii", "title": "Anatomy and Physiology II", "description": "This syllabus is a one-semester Anatomy and Physiology II course with lab or lab-adjacent activities. It assumes students have completed Anatomy and Physiology I or an equivalent introduction to anatomical terminology, tissues, integumentary, skeletal, muscular, nervous, and introductory endocrine content. Students study blood, the heart and vessels, immunity, respiration, digestion and metabolism, the urinary system, reproduction, development, and integrated homeostasis.", "topics": [{"id": "96ca1a81-28ef-4787-bd19-d0b118f31df7", "type": "topic", "title": "A&P I Bridge, Homeostasis, and Endocrine Integration", "description": "This section reviews homeostatic control, feedback loops, tissue and system integration, and endocrine signaling needed for second-semester systems.", "children": [{"id": "a693e649-c42b-44a2-bbc3-64002374d491", "type": "subtopic", "title": "Homeostatic Control Systems", "description": "These ideas explain how body systems detect change, communicate responses, and restore controlled variables.", "children": [{"id": "236d90dd-48d4-4fa3-8e12-52999d0c79a0", "type": "concept", "title": "negative feedback"}, {"id": "61d8c823-04f8-42b7-966b-70262de693f2", "type": "concept", "title": "positive feedback"}, {"id": "6335e2f3-681d-4a5c-b5b6-720651890da1", "type": "concept", "title": "receptor"}, {"id": "e9f459a1-0775-4a59-9328-3c3b0dce151d", "type": "concept", "title": "control center"}, {"id": "1f04cc37-25a1-403d-a1ac-299e2a78c3d1", "type": "concept", "title": "effector"}, {"id": "6fe53f6e-7e82-403a-b14c-e4963d22f999", "type": "concept", "title": "set point"}, {"id": "159a742d-27f7-4873-ba46-c9fd42ff8c09", "type": "concept", "title": "homeostatic imbalance"}]}, {"id": "82ca37d4-002d-4491-90e3-594767f1e918", "type": "subtopic", "title": "Endocrine Signaling", "description": "Endocrine mechanisms help students connect hormones to slow, distributed regulat